/** Brand lift card — brand_lift_card_ff1c77.html */
export function BrandLiftVisual({ className = '' }: { className?: string }) {
  const ptsRef = useRef<HTMLSpanElement>(null);
  const recallRef = useRef<HTMLDivElement>(null);
  const msgRef = useRef<HTMLDivElement>(null);
  const intentRef = useRef<HTMLDivElement>(null);
  const [visibleStats, setVisibleStats] = useState(0);

  useEffect(() => {
    const timers: number[] = [];

    const reset = () => {
      if (ptsRef.current) ptsRef.current.textContent = '+0';
      if (recallRef.current) recallRef.current.textContent = '0%';
      if (msgRef.current) msgRef.current.textContent = '0%';
      if (intentRef.current) intentRef.current.textContent = '+0';
      setVisibleStats(0);
    };

    const run = () => {
      timers.forEach(clearTimeout);
      timers.length = 0;
      reset();
      timers.push(window.setTimeout(() => animateCount(ptsRef.current, 14, 800, '+'), 150));
      timers.push(
        window.setTimeout(() => {
          setVisibleStats(1);
          animateCount(recallRef.current, 47, 800, '', '%');
        }, 500),
      );
      timers.push(
        window.setTimeout(() => {
          setVisibleStats(2);
          animateCount(msgRef.current, 62, 800, '', '%');
        }, 700),
      );
      timers.push(
        window.setTimeout(() => {
          setVisibleStats(3);
          animateCount(intentRef.current, 9, 800, '+');
        }, 900),
      );
    };

    run();
    const loop = window.setInterval(run, 4600);
    return () => {
      clearInterval(loop);
      timers.forEach(clearTimeout);
    };
  }, []);

  const stats = [
    { label: 'Recall', ref: recallRef },
    { label: 'Message', ref: msgRef },
    { label: 'Intent', ref: intentRef },
  ] as const;

  return (
    <div
      className={`flex aspect-square size-full items-center justify-center bg-[var(--v2-pink)] p-5 sm:p-6 ${className}`}
      aria-hidden
    >
      <div className="w-full max-w-[340px]">
        <div className="mb-4 rounded-[20px] border-2 border-[var(--v2-ink)] bg-white px-5 py-5 shadow-[8px_8px_0_var(--v2-ink)] sm:px-6">
          <div className="mb-2.5 flex items-center justify-between border-b border-[#eee] pb-2">
            <QareWordmark />
            <span className="font-mono text-[9px] tracking-[0.03em] text-[#999]">
              INTERACTIVE REPORT
            </span>
          </div>

          <div className="mb-3.5 flex items-start justify-between">
            <div className="text-[11px] font-extrabold tracking-[0.06em] text-[#666]">
              BRAND LIFT
            </div>
            <div className="font-mono text-sm font-medium text-[#2F5DE0]">
              <span ref={ptsRef}>+0</span> pts
            </div>
          </div>

          <div className="text-[28px] font-black tracking-[-0.01em] text-[var(--v2-ink)]">
            Aided awareness
          </div>
        </div>

        <div className="flex gap-2">
          {stats.map((stat, i) => (
            <div
              key={stat.label}
              className={`flex-1 rounded-xl border-2 border-[var(--v2-ink)] bg-white px-2.5 py-3 shadow-[4px_4px_0_var(--v2-ink)] transition-all duration-[400ms] ${
                visibleStats > i
                  ? 'translate-y-0 opacity-100'
                  : 'translate-y-2 opacity-0'
              }`}
            >
              <div className="mb-1 text-[10.5px] font-semibold text-[#888]">{stat.label}</div>
              <div
                ref={stat.ref}
                className="font-mono text-lg font-medium leading-none text-[var(--v2-ink)]"
              >
                {stat.label === 'Intent' ? '+0' : '0%'}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
